const choice = $('Listen for voice or button press').item.json.callback_query.data;

const now = new Date();
let targetDate = new Date(now);

if (choice === 'tomorrow_8') {
  targetDate.setDate(now.getDate() + 1);
} else if (choice === 'nextbizday_8') {
  const dayOfWeek = now.getDay();
  let daysToAdd = 1;
  if (dayOfWeek === 5) {
    daysToAdd = 3;
  } else if (dayOfWeek === 6) {
    daysToAdd = 2;
  } else if (dayOfWeek === 0) {
    daysToAdd = 1;
  }
  targetDate.setDate(now.getDate() + daysToAdd);
}

// We format the date in the “year-month-day” format for a specific calendar day
const year = targetDate.getFullYear();
const month = String(targetDate.getMonth() + 1).padStart(2, '0');
const day = String(targetDate.getDate()).padStart(2, '0');

// We use Luxon (built into n8n) to accurately determine 8:00 a.m. Berlin time,
// with automatic adjustment for daylight saving time
const berlinTime = DateTime.fromObject(
  { year: Number(year), month: Number(month), day: Number(day), hour: 8, minute: 0, second: 0 },
  { zone: 'Europe/Berlin' }
);

return {
  json: {
    ...$input.item.json,
    scheduled_time: berlinTime.toUTC().toISO()
  }
};

const rawText = $input.item.json.text || '';

const patterns = [
  // Gmail-стиль: "Ім'я <email>:" — не залежить від мови
  /\n[^\n]{0,120}<[^<>\n]+@[^<>\n]+>\s*:\s*\n/,

  // Outlook-стиль: підібраний список конкретних слів (нім./англ./укр./рос.),
  // що реально використовуються для "шапки" цитати
  /\n(Von|Gesendet|An|Betreff|From|Sent|To|Subject|Від|Кому|Дата|Тема|От|Отправлено|Кому|Тема):\s.{0,150}\n(Von|Gesendet|An|Betreff|From|Sent|To|Subject|Від|Кому|Дата|Тема|От|Отправлено|Кому|Тема):\s.{0,150}\n(Von|Gesendet|An|Betreff|From|Sent|To|Subject|Від|Кому|Дата|Тема|От|Отправлено|Кому|Тема):\s/
];

let cutIndex = rawText.length;
for (const pattern of patterns) {
  const match = rawText.match(pattern);
  if (match && match.index < cutIndex) {
    cutIndex = match.index;
  }
}

const cleanBody = rawText.substring(0, cutIndex).trim();

return {
  json: {
    ...$input.item.json,
    cleanBody
  }
};

const data = $('Remove quoted history from email').item.json;
const fullText = data.cleanBody;
const chunkSize = 3500;
const chunks = [];
let remaining = fullText;

while (remaining.length > 0) {
  if (remaining.length <= chunkSize) {
    chunks.push(remaining);
    break;
  }
  let splitIndex = remaining.lastIndexOf('\n\n', chunkSize);
  if (splitIndex <= 0) {
    splitIndex = chunkSize;
  }
  chunks.push(remaining.substring(0, splitIndex).trim());
  remaining = remaining.substring(splitIndex).trim();
}

const cleanFrom = data.headers.from.replace(/^From:\s*/i, '');
const cleanSubject = data.headers.subject.replace(/^Subject:\s*/i, '');

return chunks.map((chunk, index) => ({
  json: {
    chunkText: chunk,
    chunkNumber: index + 1,
    totalChunks: chunks.length,
    from: cleanFrom,
    subject: cleanSubject
  }
}));
